// _scalar_sizeSliceCodecSerial returns the length of the encoding of the
// elements of x, a []codec.Serial.
func _scalar_sizeSliceCodecSerial(x []codec.Serial) int {
	n := 0
	for k := range x {
		n += wire.SizeBytes(x[k].SizeKanon())
	}
	return n
}

// _scalar_putSliceCodecSerial writes the encoding of x, a []codec.Serial, into
// the end of buf, which has room for it, and returns its length. It fails for a
// value that fails to encode, which loc and num locate.
func _scalar_putSliceCodecSerial(buf []byte, x []codec.Serial, loc string, num int) (int, error) {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, err := _scalar_putCodecSerial(buf[:i], &x[k], loc, num)
		if err != nil {
			return 0, err
		}
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i, nil
}

// _scalar_exactputCodecSerial writes the encoding of the codec.Serial that x
// points at, which is not its zero value, into the end of buf, which has room
// for its SizeKanon, and returns its length. codec.Serial declares kanon.Exact,
// so the encoding does not fail, and a value that breaks the guarantee panics.
func _scalar_exactputCodecSerial(buf []byte, x *codec.Serial, loc string, num int) int {
	n := x.SizeKanon()
	i := len(buf) - n
	enc, err := x.AppendBinary(buf[i:i:len(buf)])
	wire.MustExact(enc, err, n, loc, num)
	return n
}

// _scalar_putGauge writes the encoding of the Gauge that x points at into the
// end of buf, which has room for it, and returns its length. It fails when x
// fails to encode itself.
func _scalar_putGauge(buf []byte, x *Gauge, loc string, num int) (int, error) {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

