// _scalar_readArray2Float32 decodes the elements that data encodes, a
// [2]float32 without its length, into *dst. It fails unless data encodes
// exactly 2 elements. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _scalar_readArray2Float32(dst *[2]float32, data []byte, slab string, off, depth int, loc string, num int) error {
	i := 0
	for k := range dst {
		u, n := wire.Uint32(data[i:])
		if n <= 0 {
			return wire.ReadError(n, loc, num, off+i)
		}
		dst[k] = math.Float32frombits(u)
		i += n
	}
	if i != len(data) {
		return wire.TrailingError(len(data)-i, loc, num, off+i)
	}
	return nil
}

// _scalar_readArray2Bool decodes the elements that data encodes, a [2]bool
// without its length, into *dst. It fails unless data encodes exactly 2
// elements. data starts at offset off of slab, and the decode enters depth
// levels below the value at most. loc and num locate the field in errors.
func _scalar_readArray2Bool(dst *[2]bool, data []byte, slab string, off, depth int, loc string, num int) error {
	i := 0
	for k := range dst {
		u, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, loc, num, off+i)
		}
		if n > 1 && data[i+n-1] == 0 {
			return wire.LongFormError(n, loc, num, off+i)
		}
		if u > 1 {
			return wire.BoolError(u, loc, num, off+i)
		}
		dst[k] = u != 0
		i += n
	}
	if i != len(data) {
		return wire.TrailingError(len(data)-i, loc, num, off+i)
	}
	return nil
}

// _scalar_readSliceDigest appends the elements that data encodes, a []Digest
// without its length, to *dst. data starts at offset off of slab, and the
// decode enters depth levels below the value at most. loc and num locate the
// field in errors.
func _scalar_readSliceDigest(dst *[]Digest, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]Digest, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		x = append(x, Digest{})
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		if n > 1 && data[i+n-1] == 0 {
			return wire.LongFormError(n, loc, num, off+i)
		}
		i += n
		x[last] = Digest{}
		if err := x[last].UnmarshalBinary(data[i : i+int(l)]); err != nil {
			return wire.UnmarshalError(err, loc, num, off+i)
		}
		{
			var scratch [128]byte
			enc, err := x[last].AppendBinary(scratch[:0])
			if err != nil || !bytes.Equal(enc, data[i:i+int(l)]) {
				return wire.EncodingError(loc, num, off+i)
			}
		}
		i += int(l)
	}
	*dst = x
	return nil
}

// _scalar_readSliceCodecSerial appends the elements that data encodes, a
// []codec.Serial without its length, to *dst. data starts at offset off of
// slab, and the decode enters depth levels below the value at most. loc and num
// locate the field in errors.
func _scalar_readSliceCodecSerial(dst *[]codec.Serial, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]codec.Serial, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		x = append(x, codec.Serial{})
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		if n > 1 && data[i+n-1] == 0 {
			return wire.LongFormError(n, loc, num, off+i)
		}
		i += n
		x[last] = codec.Serial{}
		if err := x[last].UnmarshalBinary(data[i : i+int(l)]); err != nil {
			return wire.UnmarshalError(err, loc, num, off+i)
		}
		i += int(l)
	}
	*dst = x
	return nil
}

// _scalar_tagScalars returns the error of the canonical decode of Scalars for
// the tag at data[i], which begins no field after the fields that the decode
// read before it. data starts at offset off of the slab.
func _scalar_tagScalars(data []byte, i int, prior uint64, off int) error {
	tag, n := wire.Uvarint(data[i:])
	if n <= 0 {
		return wire.ReadError(n, "Scalars", 0, off+i)
	}
	if n > 1 && data[i+n-1] == 0 {
		return wire.LongFormError(n, "Scalars", 0, off+i)
	}
	if tag>>3 == 0 {
		return wire.TagError(tag, "Scalars", 0, off+i)
	}
	if tag>>3 <= prior {
		return wire.OrderError(tag>>3, prior, "Scalars", 0, off+i)
	}
	switch tag >> 3 {
	case 1:
		return wire.FormatError(tag, wire.Varint, "Scalars.Bool", off+i)
	case 2:
		return wire.FormatError(tag, wire.Varint, "Scalars.Flag", off+i)
	case 3:
		return wire.FormatError(tag, wire.Varint, "Scalars.Int", off+i)
	case 4:
		return wire.FormatError(tag, wire.Varint, "Scalars.Int8", off+i)
	case 5:
		return wire.FormatError(tag, wire.Varint, "Scalars.Int16", off+i)
	case 6:
		return wire.FormatError(tag, wire.Varint, "Scalars.Int32", off+i)
	case 7:
		return wire.FormatError(tag, wire.Varint, "Scalars.Int64", off+i)
	case 8:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uint", off+i)
	case 9:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uint8", off+i)
	case 10:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uint16", off+i)
	case 11:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uint32", off+i)
	case 12:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uint64", off+i)
	case 13:
		return wire.FormatError(tag, wire.Varint, "Scalars.Uintptr", off+i)
	case 14:
		return wire.FormatError(tag, wire.Fixed32, "Scalars.Fixed32", off+i)
	case 15:
		return wire.FormatError(tag, wire.Fixed64, "Scalars.Fixed64", off+i)
	case 16:
		return wire.FormatError(tag, wire.Fixed32, "Scalars.Float32", off+i)
	case 17:
		return wire.FormatError(tag, wire.Fixed64, "Scalars.Float64", off+i)
	case 18:
		return wire.FormatError(tag, wire.Fixed32, "Scalars.Ratio", off+i)
	case 19:
		return wire.FormatError(tag, wire.Fixed64, "Scalars.Complex64", off+i)
	case 20:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Complex128", off+i)
	case 21:
		return wire.FormatError(tag, wire.Fixed64, "Scalars.Phase", off+i)
	case 22:
		return wire.FormatError(tag, wire.Varint, "Scalars.Duration", off+i)
	case 23:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Text", off+i)
	case 24:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Blob", off+i)
	case 25:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Key", off+i)
	case 26:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Empty", off+i)
	case 27:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Floats", off+i)
	case 28:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Bools", off+i)
	case 29:
		return wire.FormatError(tag, wire.Bytes, "Scalars.At", off+i)
	case 30:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Count", off+i)
	case 31:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Digest", off+i)
	case 32:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Stamp", off+i)
	case 33:
		return wire.FormatError(tag, wire.Varint, "Scalars.Level", off+i)
	case 34:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Digests", off+i)
	case 35:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Gauge", off+i)
	case 36:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Serial", off+i)
	case 37:
		return wire.FormatError(tag, wire.Bytes, "Scalars.Serials", off+i)
	case 38:
		return wire.FormatError(tag, wire.Varint, "Scalars.Era", off+i)
	}
	return wire.UnknownFieldError(tag>>3, "Scalars", 0, off+i)
}

// _scalar_putCodecSerial writes the encoding of the codec.Serial that x points
// at into the end of buf, which has room for it, and returns its length. The
// room is the length that the SizeKanon of x returns. It fails when x fails to
// encode itself, which kanon.Exact allows for the zero codec.Serial alone, and
// panics for an encoding of another length.
func _scalar_putCodecSerial(buf []byte, x *codec.Serial, loc string, num int) (int, error) {
	n := x.SizeKanon()
	i := len(buf) - n
	enc, err := x.AppendBinary(buf[i:i:len(buf)])
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	wire.MustExact(enc, nil, n, loc, num)
	return n, nil
}
